SELECT b.version, COUNT(*) FILTER (WHERE r.status = 'passed') AS passed, COUNT(*) FILTER (WHERE r.status = 'failed') AS failed, COUNT(*) FILTER (WHERE r.status = 'skipped') AS skipped, 100 * COUNT(*) FILTER (WHERE r.status = 'passed') / (COUNT(*) FILTER (WHERE r.status = 'passed') + COUNT(*) FILTER (WHERE r.status = 'failed')) AS pass_rate FROM builds b JOIN test_runs tr ON tr.build_id = b.build_id JOIN test_results r ON r.test_run_id = tr.test_run_id GROUP BY b.build_id, b.version HAVING COUNT(*) FILTER (WHERE r.status = 'failed') > 0;
